* {
  box-sizing: border-box;
}

body {
  font-family: Georgia, "Times New Roman", serif;
  background: #f5f0e8;
  color: #2c2416;
  line-height: 1.6;
  margin: 0;
  min-height: 100vh;
}

a {
  color: #5c4a32;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: normal;
  margin: 0 0 0.25rem;
}

h2 {
  font-size: 1.1rem;
  font-weight: normal;
  color: #6b5a42;
  margin: 2rem 0 0.75rem;
  border-bottom: 1px solid #d4c9b8;
  padding-bottom: 0.25rem;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.book-list li {
  padding: 0.6rem 0;
  border-bottom: 1px solid #e8dfd0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.book-list li:last-child {
  border-bottom: none;
}

.book-link {
  flex: 1;
}

.book-title {
  font-weight: bold;
}

.book-author {
  color: #6b5a42;
  font-size: 0.9rem;
}

.empty {
  color: #8a7a66;
  font-style: italic;
  font-size: 0.95rem;
}

form.add-form {
  background: #ebe4d6;
  padding: 1.25rem;
  border-radius: 4px;
  margin-top: 2rem;
}

form.add-form h2 {
  margin-top: 0;
  border: none;
  padding: 0;
}

label {
  display: block;
  font-size: 0.85rem;
  color: #6b5a42;
  margin-bottom: 0.25rem;
}

input,
textarea {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid #c9b99a;
  border-radius: 3px;
  font-family: inherit;
  font-size: 1rem;
  background: #faf8f4;
  margin-bottom: 0.75rem;
}

textarea {
  min-height: 80px;
  resize: vertical;
}

button,
.btn {
  background: #5c4a32;
  color: #f5f0e8;
  border: none;
  padding: 0.5rem 1rem;
  font-family: inherit;
  font-size: 0.9rem;
  border-radius: 3px;
  cursor: pointer;
}

button:hover,
.btn:hover {
  background: #4a3a28;
}

.btn-small {
  padding: 0.25rem 0.6rem;
  font-size: 0.8rem;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.5rem;
  font-size: 0.9rem;
}

.book-detail h1 {
  margin-bottom: 0.25rem;
}

.book-detail .author {
  color: #6b5a42;
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
}

.book-detail .status {
  font-size: 0.85rem;
  color: #8a7a66;
  margin-bottom: 1.5rem;
}

.book-detail .notes {
  background: #ebe4d6;
  padding: 1rem;
  border-radius: 4px;
  white-space: pre-wrap;
}

.book-detail .notes-label {
  font-size: 0.85rem;
  color: #6b5a42;
  margin-bottom: 0.5rem;
}

.book-detail .actions {
  margin-top: 1.5rem;
  display: flex;
  gap: 0.75rem;
}

